// Exnoria - sup.contact.notify
// Build WhatsApp notification payload for contact resolution update

const webhook = $("Webhook").first().json.body;
const contact = $input.first().json;

const { contact_id, ticket_id, signal_id, message_context } = webhook;

const firstname = contact.properties?.firstname?.value ?? 'Customer';
const phone     = contact.properties?.phone?.value ?? '';
const email     = contact.properties?.email?.value ?? '';

if (!phone) {
  return [{
    json: {
      contact_id,
      ticket_id,
      notified: false,
      reason: 'no_phone_number',
      email,
      firstname,
      simulated: false
    }
  }];
}

// Clean phone number (remove +, spaces, dashes)
const cleanPhone = phone.replace(/[^\d]/g, '');

const message = [
  'Hi ' + firstname + ',',
  '',
  'Update on your support request (' + (ticket_id || 'recent inquiry') + '):',
  '',
  message_context,
  '',
  'If you have further questions, please reply to this message.',
  '',
  '-- Exnoria Support'
].join('\n');

const whatsapp_payload = {
  messaging_product: 'whatsapp',
  to: cleanPhone,
  type: 'text',
  text: { body: message }
};

const notifiedAt = new Date(new Date().setUTCHours(0,0,0,0)).getTime();

return [{
  json: {
    contact_id,
    ticket_id,
    signal_id,
    email,
    firstname,
    phone: cleanPhone,
    whatsapp_payload,
    notified_at: notifiedAt,
    message_preview: message.substring(0, 100) + '...'
  }
}];

